import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract(data):
    pkgs = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (name, pkg['id'])
                pkgs[key] = pkg.get('resolvedVersion', pkg.get('requestedVersion',''))
    return pkgs

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k, 'N/A')
    av = a.get(k, 'N/A')
    if bv != av:
        changes.append((k[0], k[1], bv, av))
    else:
        unchanged.append((k[0], k[1], bv))

print('=== CHANGES ===')
for c in changes:
    print(f'{c[0]}: {c[1]} {c[2]} -> {c[3]}')
print(f'Total: {len(changes)}')
print()
print(f'=== UNCHANGED: {len(unchanged)} packages ===')
"
